"""FM-16H: original editorial reasoning pathways; marks and demand teacher pending."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,x,y,z=s.symbols('k h x y z',real=True)
PATHS={'matrix-equation':'MAT.inverse.apply','system-classification':'MAT.zero-system.classify','scalar-product':'VEC.scalar-product.calculate','plane-intersection-direction':'VEC.plane-intersection.direction'}
RATIONALES={
'matrix-equation':['Undo a nonzero scalar multiplication.','Diagnose an order error using noncommuting matrices.','Solve a left matrix equation with an inverse.','Compare left and right matrix equations and verify both solutions.','Infer an unknown entry using a structural constraint.','Classify existence of a common left/right solution including singular cases.'],
'system-classification':['Compare proportional equations.','Explain why a zero determinant does not imply inconsistency.','Classify two concrete dependent systems.','Reduce three equations and verify compatibility.','Recover the right-hand-side parameter and express all solutions.','Classify a two-parameter family and prove completeness.'],
'scalar-product':['Multiply corresponding components and sum.','Distinguish zero dot product from zero vectors.','Compute a three-dimensional scalar product.','Construct displacement vectors before taking their scalar product.','Reconstruct unknown components from independent dot-product constraints.','Classify scalar-product targets using a quadratic range proof.'],
'plane-intersection-direction':['Check a perpendicular direction by dot products.','Distinguish a plane normal from an intersection direction.','Calculate a cross product of two plane normals.','Recover normals from spanning vectors and find their common direction.','Reconstruct a missing normal component from a prescribed direction.','Classify plane pairs and their intersection directions, including parallel degeneracies.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=a+1;c=b+1
 if path=='matrix-equation':
  A=M([[a,1],[0,1]]);B=M([[b,c],[a,b]])
  if l==1:
   f=[b];q=f'Solve ${a}x={a*b}$. Explain why division is allowed.';ans=f'$x={b}$.';steps=[f'{a} is nonzero, so divide both sides by {a} to get {ans}'];hints=['Undo multiplication.','Check that the divisor is nonzero.'];mistake='Multiplying rather than dividing.'
  elif l==2:
   C=M([[1,0],[b,1]]);left=A.inv()*C;right=C*A.inv();f=[left,right,False];q=f'For A={L(A)} and B={L(C)}, the two candidates are {L(left)} for the product $A^{{-1}}B$ and {L(right)} for $BA^{{-1}}$. A student selects the latter. Without recalculating either candidate, explain which solves AX=B and why.';ans=f'$A^{{-1}}B$ = {L(left)}; $BA^{{-1}}$ = {L(right)}; only the former solves the equation.';steps=['Left-multiply by the inverse of A; this cancels A immediately to the left of X.',f'The supplied products differ: {L(left)} and {L(right)}. Only the first uses the required order.', 'Since A is invertible, AX=B has exactly one solution, so the other product cannot solve it.'];hints=['Matrix multiplication is not generally commutative.','Cancel the factor from the side on which it appears.'];mistake='Moving the inverse to the wrong side.'
  elif l==3:
   X=A.inv()*B;f=[X];q=f'Use an inverse to solve AX=B for A={L(A)} and B={L(B)}. Verify by multiplication.';ans=L(X);steps=[f'The determinant is {a}, so the inverse exists: {L(A.inv())}.',f'Left multiplication gives $X=A^{{-1}}B$ = {ans}.',f'Check AX = {L(A*X)} = B.'];hints=['Find the inverse of A.','Multiply on the left and verify.'];mistake='Calculating BA inverse.'
  elif l==4:
   C=M([[a,1],[b,2]]);X=B*C.inv();Y=C.inv()*B;f=[X,Y,X==Y];q=f'Compare the solutions of XC=B and CY=B, with C={L(C)} and B={L(B)}. Find X and Y, decide whether they are equal and verify both equations.';ans=f'X={L(X)}, Y={L(Y)}; they are different.';steps=[f'The determinant of C is {C.det()}, nonzero; its inverse is {L(C.inv())}.',f'Right-multiply the first equation to get $X=BC^{{-1}}$ = {L(X)}.',f'Left-multiply the second equation to get $Y=C^{{-1}}B$ = {L(Y)}.',f'XC = {L(X*C)} and CY = {L(C*Y)}, both equal B. The two solutions differ.'];hints=['Determine which side each inverse must act on.','Verify each candidate with its own equation.'];mistake='Using the same multiplication order for both equations.'
  elif l==5:
   C=M([[a,1],[0,1]]);D=M([[b,h],[c,b]]);X=C.inv()*D;root=a*c+b;f=[root,X.subs(h,root)];q=f'Let A={L(C)} and B={L(D)}. Given AX=B and X is symmetric, find h and the complete matrix X. Prove uniqueness.';ans=f'$h={root}$; X={L(X.subs(h,root))}.';steps=[f'Because the determinant is {a}, X is uniquely given by $A^{{-1}}B$ = {L(X)} for each h.',f'Symmetry equates the off-diagonal entries: $(h-{b})/{a}={c}$, giving h={root}.',f'Substitute to obtain {L(X.subs(h,root))}; its off-diagonal entries agree and AX=B. The linear equation for h has just one solution.'];hints=['Express X in terms of h before imposing symmetry.','Only the off-diagonal entries need to match.'];mistake='Imposing symmetry on B instead of X.'
  else:
   A=M([[a,1],[0,k]]);B=M([[b,h],[0,b]]);X=A.inv()*B;f=[X,h*(a-k),a,0];q=f'For every real pair (k,h), determine whether AX=B and XA=B can hold for the same real matrix X, where A={L(A)} and B={L(B)}. Find X whenever it exists and prove completeness, including singular A.';ans=f'Exactly when k is nonzero and $h({a}-k)=0$; then X={L(X)} uniquely.';steps=[f'B has determinant {b*b}, so B is invertible. If k=0, A is singular and AX cannot equal B (the second row is zero).',f'For nonzero k, AX=B uniquely determines X = {L(X)}.', 'The second equation is equivalent to AB=BA: substitute the inverse expression for X and multiply by A on the left.',f'The only possibly nonzero entry of AB-BA is the upper-right entry, $h({a}-k)$. Thus h=0 or k={a}, subject to k nonzero.', 'Every listed pair gives both equations, and the singular case is excluded. This proves necessity, sufficiency and uniqueness.'];hints=['Separate the singular case first.','Substitute X from the first equation into the second.'];mistake='Assuming the two multiplication orders are equivalent for any invertible matrix.'
 elif path=='system-classification':
  if l==1:
   f=[False];q=f'Can a real number x satisfy both $x={a}$ and $2x={2*a+1}$? Explain.';ans='No.';steps=[f'Doubling the first equation gives $2x={2*a}$, contradicting the second.'];hints=['Compare the equations after scaling.','A variable cannot satisfy two different values at once.'];mistake='Treating the equations as separate problems.'
  elif l==2:
   f=[True,False];q=f'Both systems have coefficient rows (1,{a}) and (2,{2*a}). System I has right sides {b},{2*b}; system II has {b},{2*b+1}. A student says both have no solutions because their determinants vanish. Explain the distinction.';ans='I: infinitely many; II: none.';steps=['The coefficient rows are proportional, so neither system can have a unique solution.',f'In I the right sides have the same factor 2, so the second equation repeats the first; y is free.',f'In II the second right side is not twice {b}, so subtraction gives 0=1.'];hints=['Compare right sides as well as coefficient rows.','A repeated equation leaves a free variable.'];mistake='Equating singularity with inconsistency.'
  elif l==3:
   f=[M([b-a*y,y]),False];q=f'Solve or show inconsistent: (I) $x+{a}y={b}$, $3x+{3*a}y={3*b}$; (II) $x+{a}y={b}$, $3x+{3*a}y={3*b+2}$. Give all solutions where appropriate.';ans=f'I: $(x,y)=({b}-{a}y,y)$ for all real y; II: none.';steps=['Subtract three times the first equation from the second in each system.',f'I gives 0=0, hence x={b}-{a}y with y free.', 'II gives 0=2, a contradiction.'];hints=['Eliminate x using the proportional rows.','Distinguish a tautology from a contradiction.'];mistake='Giving one particular solution for a non-unique system.'
  elif l==4:
   f=[M([b-z,c-a*z,z]),False];q=f'Consider $x+z={b}$, $y+{a}z={c}$ and $x+y+{a+1}z=d$. Determine all solutions for d={b+c} and determine whether solutions exist for d={b+c+1}.';ans=f'For d={b+c}: $(x,y,z)=({b}-z,{c}-{a}z,z)$ for all real z. For d={b+c+1}: none.';steps=['Add the first two equations to get the left side of the third.',f'The third right side must be {b+c}. When equal, the third equation is redundant.',f'Solve the first two equations with z free to obtain {L(f[0])}; otherwise the third equation contradicts their sum.'];hints=['Look for a dependence among all three rows.','Use one variable as a free parameter.'];mistake='Assuming three equations in three unknowns always have one solution.'
  elif l==5:
   f=[b+2*c,M([b-z,c-a*z,z])];q=f'Find the value of h for which $x+z={b}$, $y+{a}z={c}$, $x+2y+{1+2*a}z=h$ is consistent. Give every solution and show there cannot be a unique solution.';ans=f'$h={b+2*c}$; all $(x,y,z)=({b}-z,{c}-{a}z,z)$, z real.';steps=['The third left side equals the first plus twice the second.',f'Consistency therefore requires $h={b}+2({c})={b+2*c}$.',f'This value makes the third redundant. The first two equations give {L(f[1])}, with z free.', 'All real z yield solutions, proving non-uniqueness; any other h gives a contradiction.'];hints=['Use the same row combination on both sides.','Describe the whole solution family.'];mistake='Finding h without stating all solutions.'
  else:
   f=[b+c,M([b-(h-b-c)/k,c-a*(h-b-c)/k,(h-b-c)/k]),M([b-z,c-a*z,z])];q=f'For every real k,h classify the system $x+z={b}$, $y+{a}z={c}$, $x+y+({a+1}+k)z=h$ as having one, none or infinitely many solutions. Give all solutions and prove the classification is exhaustive.';ans=f'k nonzero: unique {L(f[1])}; k=0 and h={b+c}: family {L(f[2])}, z real; otherwise none.';steps=[f'Subtract the first two equations from the third to obtain $kz=h-{b+c}$.',f'When k is nonzero, this determines z; substitute into the first two equations to obtain {L(f[1])}.',f'When k=0 and h={b+c}, the reduced equation is 0=0, so all {L(f[2])} with real z solve the system.',f'When k=0 and h differs from {b+c}, the reduced equation is a contradiction.', 'Row subtraction preserves the solution set; these three disjoint cases exhaust all parameters.'];hints=['Eliminate x and y before dividing by k.','Keep the k=0 branch separate.'];mistake='Dividing by a parameter that might be zero.'
 elif path=='scalar-product':
  U=M([a,b,c]);V=M([2,-1,3]);
  if l==1:
   f=[a-2*b+3*c];q=f'Evaluate ${a}(1)+{b}(-2)+{c}(3)$, retaining the negative contribution.';ans=L(f[0]);steps=[f'The three signed terms are {a}, {-2*b}, {3*c}; their sum is {ans}.'];hints=['Multiply each pair first.','Keep the sign of the middle term.'];mistake='Dropping a negative sign.'
  elif l==2:
   D=M([b,-a,0]);E=M([a,b,0]);f=[0,False];q=f'For u={L(E)} and v={L(D)}, a student claims a zero scalar product means one vector is zero. Explain using these vectors and give their scalar product.';ans='Dot product 0; neither vector is zero.';steps=[f'The dot product is ${a*b}-{a*b}+0=0$.','Both vectors have nonzero components; instead, they are perpendicular.'];hints=['Inspect the vectors before computing.','Zero dot product of nonzero vectors indicates perpendicularity.'];mistake='Confusing the scalar product with scalar multiplication.'
  elif l==3:
   f=[U.dot(V)];q=f'Calculate the scalar product of {L(U)} and {L(V)}.';ans=L(f[0]);steps=[f'Multiply corresponding components: {2*a}, {-b}, {3*c}.',f'Add the signed products to get {ans}.'];hints=['Use matching components.','The result is a scalar.'];mistake='Returning a vector of component products.'
  elif l==4:
   U=M([a+1,b,c-1]);V=M([1,-2,3]);P=M([1,2,3]);Q=P+U;R=M([2,0,1]);S=R+V;f=[U,V,U.dot(V)];q=f'Given points P={L(P)}, Q={L(Q)}, R={L(R)}, S={L(S)}, calculate the scalar product of the directed displacements PQ and RS. State the effect of reversing PQ only.';ans=f'{L(U.dot(V))}; reversing PQ gives {L(-U.dot(V))}.';steps=[f'Subtract the start from the end of each displacement: PQ={L(U)}, RS={L(V)}.',f'The scalar product is {L(U.dot(V))}.',f'Reversing PQ negates one factor, so the result is {L(-U.dot(V))}.'];hints=['Build displacement vectors first.','Reversing one vector changes the sign.'];mistake='Taking dot products of position vectors rather than displacements.'
  elif l==5:
   E=M([1,a,0]);F=M([b,1,1]);target1=a+2*a*b;target2=b*a+2*b+c;sol=M([a,2*b,c]);f=[sol];q=f'A vector w=(x,y,{c}) has scalar product {target1} with {L(E)} and {target2} with {L(F)}. Determine w and prove uniqueness.';ans=L(sol);steps=[f'The two scalar products give $x+{a}y={target1}$ and ${b}x+y+{c}={target2}$.',f'The coefficient determinant is $1-{a*b}$, nonzero. Eliminating x gives y={2*b}, then x={a}.',f'Both dot-product constraints hold for {ans}; nonzero determinant ensures uniqueness.'];hints=['Convert each dot product to an equation.','Check the two coefficient rows are independent.'];mistake='Using only one scalar-product constraint.'
  else:
   U=M([k,k-a,b]);V=M([k-a,k,1]);expr=s.expand(U.dot(V));mid=s.Rational(a,2);minimum=b-s.Rational(a*a,2);f=[expr,minimum,mid,0,1,2];q=f'For real k let u={L(U)} and v={L(V)}. For every prescribed scalar product h, determine all real k with u dot v=h. Prove the minimum possible scalar product and classify the number of solutions.';ans=f'Minimum {L(minimum)} at k={L(mid)}. Below it no solutions; at it one; above it two, $k={s.latex(mid)}\\pm\\sqrt{{(h-({s.latex(minimum)}))/2}}$.';steps=[f'Multiply corresponding components and sum: u dot v = {L(expr)}.',f'Complete the square: $2(k-{s.latex(mid)})^2+({s.latex(minimum)})$.',f'The nonnegative square gives minimum {L(minimum)}, attained only at k={L(mid)}.',f'Equating to h determines the squared term. A negative, zero or positive right side gives 0, 1 or 2 distinct real roots. The roots are those in {ans}', 'All roots satisfy the original dot-product equation, so the classification is exhaustive.'];hints=['Compute the dot product as a polynomial in k.','Complete the square before solving the inverse problem.'];mistake='Assuming a dot product cannot be negative or discarding one square-root branch.'
 elif path=='plane-intersection-direction':
  N=M([1,a,0]);P=M([0,1,b]);D=N.cross(P)
  if l==1:
   f=[0];q=f'Check whether the direction {L(M([a,-1,0]))} is perpendicular to the normal {L(N)} using a scalar product.';ans='Yes; dot product 0.';steps=[f'The scalar product is ${a}-{a}+0=0$. Both vectors are nonzero, so they are perpendicular.'];hints=['Use the dot product.','Check neither vector is zero.'];mistake='Using componentwise equality to test perpendicularity.'
  elif l==2:
   f=[N.dot(P),False];q=f'Two planes have normals {L(N)} and {L(P)}. A student proposes the first normal as a direction of their common line. Explain why this cannot work, and calculate the scalar product of the normals.';ans=f'The first normal is perpendicular to its own plane, not a direction within it; normal dot product = {N.dot(P)}.';steps=[f'The first normal has dot product {N.dot(N)} with itself, not zero, so it is not parallel to its own plane.',f'The normal dot product is {N.dot(P)}. A common-line direction must be perpendicular to both normals, not simply one normal.'];hints=['A direction lying in a plane is perpendicular to its normal.','Check the proposed direction against its own plane.'];mistake='Confusing a normal with a tangent direction.'
  elif l==3:
   f=[D];q=f'Find a nonzero direction vector of the common line of the planes $x+{a}y={c}$ and $y+{b}z={a}$. Verify perpendicularity to both normals.';ans=L(D);steps=[f'Read the normals as {L(N)} and {L(P)}.',f'Their cross product is {ans}, nonzero, so the planes intersect in a line.', 'Its dot products with both normals are zero, confirming the direction.'];hints=['Read the coefficients as normals.','Take their cross product.'];mistake='Using the scalar product instead of the vector product.'
  elif l==4:
   E=M([0,0,1]);F=M([a+1,-1,0]);G=M([1,0,0]);H=M([0,b+1,-1]);NN=E.cross(F);PP=G.cross(H);DD=NN.cross(PP);f=[NN,PP,DD];q=f'One plane contains the origin and independent directions {L(E)}, {L(F)}. A second plane contains the origin and independent directions {L(G)}, {L(H)}. Find their normals and a nonzero direction of the intersection line.';ans=f'Normals {L(NN)}, {L(PP)}; direction {L(DD)}.';steps=[f'Cross the two spanning directions of each plane to get normals {L(NN)} and {L(PP)}.',f'The normals are not parallel because their cross product is {L(DD)}, nonzero.', 'Both planes pass through the origin. The common direction is perpendicular to both normals and therefore lies in both planes.'];hints=['Each pair of spanning vectors gives its plane normal.','Cross the normals, not two arbitrary spanning directions.'];mistake='Using a spanning vector from just one plane.'
  elif l==5:
   NN=M([1,a,0]);PP=M([k,1,b]);DD=M([a*b,-b,1-a*c]);f=[c,DD];q=f'The planes $x+{a}y=0$ and $kx+y+{b}z=0$ have an intersection line with direction {L(DD)}. Find k and verify that the line has exactly this direction up to scaling.';ans=f'$k={c}$; cross product of the normals is {L(DD)}.';steps=[f'The specified direction is already perpendicular to the first normal. Its dot product with the second is ${a*b}k-{b}+{b}(1-{a*c})={a*b}(k-{c})$.',f'Setting this to zero gives k={c}.',f'At that value the cross product of the normals is {L(DD)}, nonzero, so the intersection is a line with the given direction.'];hints=['A prescribed direction must be perpendicular to both normals.','Use the second normal to solve for k.'];mistake='Equating components of a normal and the line direction.'
  else:
   NN=M([1,a,0]);PP=M([k,a*k+h,0]);DD=NN.cross(PP);f=[DD,k*c,0,1,2];q=f'Let (k,h,d) be real, with (k,h) not both zero. The planes are $x+{a}y={c}$ and $kx+({a}k+h)y=d$. Classify all parameter values for which their intersection is empty, a line or a plane. Give a direction whenever it is a line, and prove the classification is exhaustive.';ans=f'h nonzero: common line parallel to (0,0,1). h=0, d={c}k: coincident planes; h=0, d differs from {c}k: disjoint parallel planes.';steps=[f'The two normals are {L(NN)} and {L(PP)}. Neither is zero under the stated restriction.',f'Their cross product is {L(DD)}. If h is nonzero, the normals are independent and the intersection direction is (0,0,1).',f'Subtract k times the first equation from the second to get $hy=d-{c}k$. If h is nonzero, y is determined, then x is determined, and z is free, establishing existence of the line.',f'If h=0, then k is nonzero. The equations represent the same plane exactly when d={c}k, otherwise parallel distinct planes.', 'These cases exhaust all allowed parameters; no zero normal has been included.'];hints=['Cross the normals to test independence.','In the parallel case compare the constants after scaling.'];mistake='Treating a zero cross product as a direction or assuming parallel planes always coincide.'
 else:raise AssertionError(path)
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
